/** Mirrors the server's data contracts (enrollment.types.ts and notification.types.ts). */
export interface CourseSummary {
  id: string;
  title: string;
  capacity: number;
  seatsLeft: number;
}

export interface Enrollment {
  id: string;
  studentId: string;
  courseId: string;
  status: "confirmed" | "rejected";
  reason?: "COURSE_FULL" | "ALREADY_ENROLLED";
}

export interface Notification {
  id: string;
  recipientId: string;
  kind: "enrollment-confirmed" | "enrollment-rejected";
  message: string;
  enrollmentId: string;
}

export interface CourseDeskApi {
  courses(): Promise<CourseSummary[]>;
  enroll(studentId: string, courseId: string): Promise<Enrollment>;
  notifications(recipientId: string): Promise<Notification[]>;
}

export function httpApi(base = "/api", fetchImpl: typeof fetch = fetch): CourseDeskApi {
  const json = async <T,>(res: Response): Promise<T> => {
    if (!res.ok) throw new Error(`${res.status} ${res.statusText}`);
    return (await res.json()) as T;
  };
  return {
    courses: async () => json(await fetchImpl(`${base}/courses`)),
    enroll: async (studentId, courseId) =>
      json(await fetchImpl(`${base}/enrollments`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ studentId, courseId }) })),
    notifications: async (recipientId) => json(await fetchImpl(`${base}/notifications?recipientId=${encodeURIComponent(recipientId)}`)),
  };
}
import { useEffect, useState } from "react";
import type { CourseDeskApi, CourseSummary, Enrollment, Notification } from "./api/client";
import { EnrollmentForm } from "./components/EnrollmentForm";
import { NotificationList } from "./components/NotificationList";

export function App({ api }: { api: CourseDeskApi }) {
  const [courses, setCourses] = useState<CourseSummary[]>([]);
  const [last, setLast] = useState<Enrollment | null>(null);
  const [inbox, setInbox] = useState<{ recipientId: string; items: Notification[] } | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    api.courses().then(setCourses, (e: Error) => setError(e.message));
  }, [api]);

  const enroll = async (studentId: string, courseId: string) => {
    try {
      setError(null);
      const enrollment = await api.enroll(studentId, courseId);
      setLast(enrollment);
      // The outcome reaches the student as a notification, so show their inbox next.
      const [items, updated] = await Promise.all([api.notifications(studentId), api.courses()]);
      setInbox({ recipientId: studentId, items });
      setCourses(updated);
    } catch (e) {
      setError((e as Error).message);
    }
  };

  return (
    <main>
      <h1>Course Desk</h1>
      <EnrollmentForm courses={courses} onEnroll={(s, c) => void enroll(s, c)} />
      {last && (
        <p role="status">
          Enrollment {last.id}: {last.status}
          {last.reason ? ` (${last.reason})` : ""}
        </p>
      )}
      {error && <p role="alert">{error}</p>}
      {inbox && <NotificationList recipientId={inbox.recipientId} items={inbox.items} />}
    </main>
  );
}
import { useState } from "react";
import type { FormEvent } from "react";
import type { CourseSummary } from "../api/client";

interface Props {
  courses: CourseSummary[];
  onEnroll(studentId: string, courseId: string): void;
}

export function EnrollmentForm({ courses, onEnroll }: Props) {
  const [studentId, setStudentId] = useState("stu-ada");
  const [courseId, setCourseId] = useState("");
  const selected = courseId || courses[0]?.id || "";

  const submit = (e: FormEvent) => {
    e.preventDefault();
    if (studentId.trim() && selected) onEnroll(studentId.trim(), selected);
  };

  return (
    <form onSubmit={submit} aria-label="Enroll">
      <label>
        Student ID <input value={studentId} onChange={(e) => setStudentId(e.target.value)} />
      </label>
      <label>
        Course{" "}
        <select value={selected} onChange={(e) => setCourseId(e.target.value)}>
          {courses.map((c) => (
            <option key={c.id} value={c.id}>
              {c.title} ({c.seatsLeft} of {c.capacity} seats left)
            </option>
          ))}
        </select>
      </label>
      <button type="submit">Enroll</button>
    </form>
  );
}
import type { Notification } from "../api/client";

export function NotificationList({ recipientId, items }: { recipientId: string; items: Notification[] }) {
  return (
    <section aria-label="Notifications">
      <h2>Notifications for {recipientId}</h2>
      {items.length === 0 ? (
        <p>No notifications yet.</p>
      ) : (
        <ul>
          {items.map((n) => (
            <li key={n.id} data-kind={n.kind}>
              {n.message}
            </li>
          ))}
        </ul>
      )}
    </section>
  );
}
import type { INestApplication } from "@nestjs/common";

/** Shared by main.ts and the e2e tests, so both serve the same routes. */
export function configureApp(app: INestApplication): INestApplication {
  app.setGlobalPrefix("api");
  app.enableCors();
  return app;
}

